using Microsoft.Data.Sqlite;

using var verbindung =
    new SqliteConnection(
        "Data Source=schule.db");
verbindung.Open();

using var befehl =
    verbindung.CreateCommand();
befehl.CommandText = """
    CREATE TABLE IF NOT EXISTS schueler (
      id      INTEGER PRIMARY KEY,
      name    TEXT NOT NULL,
      klasse  TEXT NOT NULL,
      schnitt REAL
    )
    """;
befehl.ExecuteNonQuery();

befehl.CommandText =
    "UPDATE schueler SET klasse = '4AHIF'"
  + " WHERE klasse = '3AHIF'";
int geaendert = befehl.ExecuteNonQuery();
Console.WriteLine(geaendert); // z. B. 2

befehl.CommandText =
    "SELECT COUNT(*) FROM schueler";
int anzahl = Convert.ToInt32(
    befehl.ExecuteScalar());

befehl.CommandText = """
    SELECT id, name FROM schueler
    WHERE klasse = '3AHIF'
    ORDER BY name
    """;
using var reader =
    befehl.ExecuteReader();
while (reader.Read())
{
    int id = reader.GetInt32(0);
    string name = reader.GetString(1);
    Console.WriteLine($"{id}: {name}");
}
// 1: Anna
// 2: Ben

